package com.tekwatt.ocpp.controller;import com.tekwatt.ocpp.dto.*;import com.tekwatt.ocpp.service.OcppCommandService;import com.tekwatt.ocpp.service.OcppCommandTracker;import jakarta.validation.Valid;import java.util.Map;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/ocpp/commands")public class OcppCommandController{private final OcppCommandService service;private final OcppCommandTracker tracker;public OcppCommandController(OcppCommandService s,OcppCommandTracker t){service=s;tracker=t;}@PostMapping("/firmware")Map<String,String>firmware(@Valid@RequestBody FirmwareCommandRequest r){return Map.of("messageId",service.firmware(r));}@PostMapping("/remote-start")Map<String,String>remoteStart(@Valid@RequestBody RemoteStartRequest r){return Map.of("messageId",service.remoteStart(r));}@PostMapping("/remote-stop")Map<String,String>remoteStop(@Valid@RequestBody RemoteStopRequest r){return Map.of("messageId",service.remoteStop(r));}@PostMapping("/reserve-now")Map<String,String>reserveNow(@Valid@RequestBody ReserveNowRequest r){return Map.of("messageId",service.reserveNow(r));}@PostMapping("/cancel-reservation")Map<String,String>cancelReservation(@Valid@RequestBody CancelReservationRequest r){return Map.of("messageId",service.cancelReservation(r));}@PostMapping("/unlock-connector")Map<String,String>unlockConnector(@Valid@RequestBody UnlockConnectorRequest r){return Map.of("messageId",service.unlockConnector(r));}@GetMapping("/{messageId}/result")OcppCommandTracker.Result result(@PathVariable String messageId){return tracker.result(messageId);}}
